import itertools
import math
from pandas import Series

def task_func(elements, subset_size, top_n=2):
    if subset_size <= 0 or subset_size > len(elements):
        return 1, Series([], dtype='int64')

    sums = [sum(combo) for combo in itertools.combinations(elements, subset_size)]
    product = math.prod(sums)
    top_sums = sorted(sums, reverse=True)[:max(0, top_n)]

    return product, Series(top_sums)
